const e=[{Claim:"Built from Gibraltar Cultural Services' own official '69th Gibraltar International Drama Festival 2026 Rules' document (festival held 23-28 March 2026 at Ince's Hall Theatre) - a real, 69-year-running amateur one-act-play festival, a member of the National Drama Festival Association (UK), open to Adult amateur groups and Youth groups (all acting parts performed by participants aged 17 or under). Unlike this session's other performing-arts templates, this is a single-production whole-play festival for theatre groups, not a multi-item talent festival - reflected here as one real item (One-Act Play) assigned to the two real divisions the rules define.",SourceType:"Primary - Gibraltar Cultural Services official '69th Gibraltar International Drama Festival 2026 Rules'",Source:"https://www.culture.gi/wp-content/uploads/2024/10/Gibraltar-International-Drama-Festival-2026-Rules.pdf",Url:"https://www.culture.gi/wp-content/uploads/2024/10/Gibraltar-International-Drama-Festival-2026-Rules.pdf"},{Claim:"The two real divisions are Adult ('a society predominantly for those over statutory school leaving age') and Youth ('a society with all acting parts performed by young participants aged 17 or under'), per the rules' own ENTRY section (clause 1). Modeled here as ages 18-120 (Adult) and 6-17 (Youth, floored at typical statutory school starting age) since the rules define these by cast composition rather than a numeric age band.",SourceType:"Primary - Gibraltar International Drama Festival 2026 Rules, ENTRY section, clause 1",Source:"Gibraltar International Drama Festival 2026 Rules, ENTRY section",Url:""},{Claim:"The real time limit is a minimum of 20 minutes and maximum of 55 minutes (with a further 10-minute allowance at the adjudicator's discretion before points are deducted) per the PERFORMANCE section, clause 3; this template uses the real stated maximum of 55 minutes. The real entrance arrangement is not a standard fee but a refundable GBP 100 deposit per entry (FINANCES/ENTRY sections), returned once the Group gives its public performance - reproduced here as the Fees value since the schema has no separate refundable-deposit field. The 'Best Play Award' is marked out of a real published total of 100 points, covering Acting, Production and Endeavour, Originality, Stage Presentation and Theatrical Attainment (ADJUDICATION section, clause 10) - reproduced here as the real MaximumScore rather than this corpus's usual nominal 10-point scale, since the source itself publishes this number.",SourceType:"Primary - Gibraltar International Drama Festival 2026 Rules, PERFORMANCE, FINANCES and ADJUDICATION sections",Source:"Gibraltar International Drama Festival 2026 Rules, PERFORMANCE/FINANCES/ADJUDICATION sections",Url:""}],t="This is a deliberately minimal template: the source festival genuinely has only two real divisions (Adult, Youth) and one real production type (one-act play or approved extract) rather than a multi-item matrix, so one item x two groups is a faithful representation, not a truncation. No numeric per-category point breakdown (Acting/Production/Originality/etc.) is published beyond the overall 100-point total, so Grades and Ranks are left empty; the festival instead awards 14 real named trophies (Best Play, Best Actor/Actress, Best Youth Actor/Actress, Best Director, Best Original Script, Best Set/Technical Presentation and four Supporting-role awards) at the adjudicator's discretion, plus a GBP 1,000 cash prize for Best Play and a GBP 4,000 bursary if the winning play qualifies for the National Drama Festival UK.",a=[{GroupName:"Youth",AgeFrom:6,AgeTo:17,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp"},{GroupName:"Adult",AgeFrom:18,AgeTo:120,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/adult.webp"}],i=[{CompetitionItem:0,Title:"One-Act Play",Category:42,CategoryCategoryName:"Action",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/ekankika-one-act-play.webp"}],r=[{CompetitionItem:0,CompetitionItemTitle:"One-Act Play",Group:0,GroupGroupName:"Youth",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:100,MaximumMinutes:55,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,TimeCalculation:"PerHead"},{CompetitionItem:0,CompetitionItemTitle:"One-Act Play",Group:0,GroupGroupName:"Adult",ParticipantType:2,ParticipantTypeTitle:"Team",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:100,MaximumMinutes:55,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:2,TimeCalculation:"PerHead"}],n=[],o=[],s={Evidence:e,MaintenanceNote:t,AgeWiseGroups:a,CompetitionItems:i,CompetitionsAssignedToGroup:r,Grades:n,Ranks:o};export{a as AgeWiseGroups,i as CompetitionItems,r as CompetitionsAssignedToGroup,e as Evidence,n as Grades,t as MaintenanceNote,o as Ranks,s as default};
